import hashlib
import os

def compute_md5_hash(file_path):
    BLOCK_SIZE = 65536
    md5_hash = hashlib.md5()

    if not os.path.exists(file_path):
        return None

    with open(file_path, 'rb') as file:
        while True:
            data = file.read(BLOCK_SIZE)
            if not data:
                break
            md5_hash.update(data)

    return md5_hash.hexdigest()
