        return {""error"": ""Invalid date"", ""lang"": languages[lang]}

@app.route(""/api/get_day_of_week"", methods=[""GET""])
def get_day_of_week_api():
    lang = request.args.get(""lang"", default=""en"")
    if lang not in languages:
        return jsonify({""error"": ""Unsupported language""}), 400
    date = request.args.get(""date"", default=None)
    if date is None or not date.startswith(""20""):
        return jsonify({""error"": ""Invalid date""}), 400

    result = get_day_of_week(date, lang=lang)

    if isinstance(result, dict):
        return jsonify(result), 200
    else:
        return jsonify({""day_of_week"": result}), 200

if __name__ == ""__main__"":
    app.run(debug=True)

