def find_non_repeating_elements(lst):
    seen = set()
    for i in range(len(lst)):
        if lst[i] in seen:
            continue
        count = 0
        for j in range(len(lst)):
            if lst[j] == lst[i]:
                count += 1
        if count == 1:
            return [lst[i], next(k for k in lst if k != lst[i])]
