import sys
import requests

def fetch_user_profile(api_key, user_id, access_token):
    url = f""https://api.example.com/profile?api_key={api_key}&user_id={user_id}""
    headers = {'Authorization': f'Bearer {access_token}'}

    try:
        response = requests.get(url, headers=headers)
        response.raise_for_status()
        user_profile = response.json()
        return user_profile
    except requests.RequestException as e:
        print(f""Error fetching user profile: {e}"")
    except ValueError:
        print(""Error parsing API response"")

def parse_args():
    if len(sys.argv) < 4:
        print(""Usage: python script.py access_token api_key user_id"")
        sys.exit(1)

    access_token = sys.argv[1]
    api_key = sys.argv[2]
    user_id = sys.argv[3]

    return access_token, api_key, user_id

def main():
    access_token, api_key, user_id = parse_args()

    try:
        user_profile = fetch_user_profile(api_key, user_id, access_token)
        print(user_profile)
    except Exception as e:
        print(e)

if __name__ == ""__main__"":
    main()
