class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None


def generate_bst(max_depth, num_nodes, data_capacity):
    if max_depth < 1 or num_nodes < 1:
        return None

    class BST:
        def __init__(self, max_depth, num_nodes, data_capacity):
            self.max_depth = max_depth
            self.num_nodes = num_nodes
            self.data_capacity = data_capacity
            self.root = None
            self.nodes = [None] * (1 << max_depth)

        def insert(self, val):
            if not self.root:
                self.root = Node(val)
                return

            node = self.root
            for _ in range(self.max_depth - 1, -1, -1):
                bit = (1 << _) & ((1 << self.max_depth) - 1)
                if bit & val:
                    if not node.right:
                        node.right = Node(val)
                        break
                    node = node.right
                else:
                    if not node.left:
                        node.left = Node(val)
                        break
                    node = node.left

        def print_tree(self, node=None, level=0):
            if not node:
                node = self.root

            if node:
                self.print_tree(node.right, level + 1)
                print(' ' * 4 * (self.max_depth - level - 1) + str(node.val))
                self.print_tree(node.left, level + 1)

    bst = BST(max_depth, num_nodes, data_capacity)

    for _ in range(num_nodes):
        val = random.randint(0, (1 << self.max_depth) - 1)
        bst.insert(val)

    bst.print_tree()
