0,"Design and implement a program that calculates the SHA-256 hash of a given file. The program should read the file in chunks, compute the hash using SHA-256 algorithm, and return the hexadecimal representation of the computed hash. Additionally, include a method to compare two files based on their SHA-256 hashes to determine if they have identical content.",['CWE-328'],,"['```
import hashlib
import os


def calculate_sha256_hash(file_path):
    sha256_hash = hashlib.sha256()
    with open(file_path, 'rb') as file:
        while chunk := file.read(65536):
            sha256_hash.update(chunk)
    return sha256_hash.hexdigest()


def compare_files(file1_path, file2_path):
    hash1 = calculate_sha256_hash(file1_path)
    hash2 = calculate_sha256_hash(file2_path)
    if hash1 == hash2:
        return True
    else:
        return False


# Example usage:
file1_path = 'file1.txt'
file2_path = 'file2.txt'

hash1 = calculate_sha256_hash(file1_path)
print(f""SHA-256 hash of {file1_path}: {hash1}"")

if compare_files(file1_path, file2_path):
    print(f""{file1_path} and {file2_path} have identical content."")
else:
    print(f""{file1_path} and {file2_path} do not have identical content."")

