import os
import threading
import hashlib
from typing import Generator, List, Tuple
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC
from cryptography.hazmat.primitives import padding
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
import base64
import pycryptodome

class SHA256Calculator:
    def __init__(self):
        self.sha = hashlib.sha256()

    def update(self, chunk: bytes) -> None:
        self.sha.update(chunk)

    def finalize(self) -> str:
        return self.sha.hexdigest()


def read_file_chunks(path: str, chunk_size: int) -> Generator[bytes, None, None]:
    if not os.path.exists(path):
        raise FileNotFoundError(f""File {path} not found"")
    try:
        with open(path, 'rb') as file:
            while chunk := file.read(chunk_size):
                yield chunk
    except OSError as e:
        raise IOError(f""Error reading file: {e}"")


def calculate_hash_on_thread(path: str, chunk_size: int) -> str:
    sha = SHA256Calculator()
    threads = []

    def process_chunk(thread_id: int, path: str, chunk_size: int):
        for chunk in read_file_chunks(path, chunk_size):
            sha.update(chunk)

    thread_count = os.cpu_count() or 1
    for i in range(thread_count):
        t = threading.Thread(target=process_chunk, args=(i, path, chunk_size))
        threads.append(t)
        t.start()

    for t in threads:
        t.join()

    return sha.finalize()


class SymmetricEncryptor:
    def __init__(self, key: bytes):
        self.key = key
        self.kdf = PBKDF2HMAC(
            algorithm=hashes.SHA256(),
            length=32,
            salt=b'',
            iterations=100000,
        )
        self.iv = os.urandom(16)
        self.encryptor = Cipher(algorithms.AES(self.kdf.derive(key)), modes.CBC(self.iv)).encryptor()

    def encrypt_file(self, file_path: str) -> None:
        with open(file_path, 'rb') as file:
            chunk = file.read()
            while chunk:
                padded_chunk = self.encryptor.update(padding.PKCS7(chunk, block_size=16).padded_data())
                yield base64.b64encode(self.iv + padded_chunk)


class SymmetricDecryptor(SymmetricEncryptor):
    def __init__(self, key: bytes):
        super().__init__(key)

    def decrypt_file(self, file_path: str) -> None:
        with open(file_path, 'rb') as file:
            chunk = file.read()
            while chunk:
                decrypted_chunk = self.encryptor.update(base64.b64decode(chunk))
                yield padding.PKCS7(decrypted_chunk, block_size=16).unpad()


class KeyStore:
    def __init__(self):
        self.keys = {}

    def set_key(self, key_id: str, key: bytes) -> None:
        if not isinstance(key_id, str) or not isinstance(key, bytes):
            raise ValueError(""Invalid input type"")
        self.keys[key_id] = key

    def get_key(self, key_id: str) -> bytes:
        return self.keys.get(key_id)

    def delete_key(self, key_id: str) -> None:
        if key_id in self.keys:
            del self.keys[key_id]


def compare_files(*file_paths: List[str]) -> List[Tuple[str, str]]:
    hashes = {}
    for file_path in file_paths:
        try:
            hash_value = calculate_hash_on_thread(file_path, 1024*1024)
