import requests
import time
from email.mime.text import MIMEText
from smtplib import SMTP
import json
import matplotlib.pyplot as plt
import seaborn as sns
import pandas as pd

# API Endpoints and Keys
open_weather_map_api = 'https://api.openweathermap.org/data/2.5/weather'
dark_sky_api = 'https://api.darksky.net/forecast'
wunderground_api = 'http://api.wunderground.com/api'

# User Settings
user_preferences = {
    'frequency': 300,  # seconds
    'temperature_range': (20, 30),
    'wind_speed': (5, 15)
}

# Email Settings
email_settings = {
    'username': 'your_email@gmail.com',
    'password': 'your_password',
    'to_address': 'recipient@example.com'
}

def get_weather_data(api):
    try:
        response = requests.get(api)
        if response.status_code == 200:
            return json.loads(response.text)
        else:
            print(f""Failed to retrieve data from {api}: {response.status_code}"")
            return None
    except Exception as e:
        print(f""Error occurred: {e}"")
        return None

def analyze_weather_data(data):
    # Categorize weather conditions into predefined thresholds for alerting users
    if data['temp'] > user_preferences['temperature_range'][1]:
        return 'severe'
    elif data['temp'] > user_preferences['temperature_range'][0]:
        return 'moderate'
    else:
        return 'mild'

def send_email_notification(data):
    msg = MIMEText(f""Current weather: {data['weather']}."")
    msg['Subject'] = f""Weather Alert - {data['location']}""

    try:
        server = SMTP(email_settings['username'], email_settings['password'])
        server.sendmail(email_settings['to_address'], [email_settings['to_address']], msg.as_string())
        print(""Email sent successfully."")
    except Exception as e:
        print(f""Error occurred while sending email: {e}"")

def get_historical_data(start_date, end_date):
    historical_data = []
    for date in pd.date_range(start_date, end_date):
        api_response = get_weather_data(api=f""{dark_sky_api}/{user_preferences['latitude']},{user_preferences['longitude']}?timestamp={int(date.timestamp())}"")
        if api_response:
            historical_data.append(api_response)
    return historical_data

def plot_historical_data(data):
    sns.set()
    plt.figure(figsize=(10, 6))
    for i, day in enumerate(data):
        plt.plot(pd.date_range(day['time'], periods=8), [x['temperature'] for x in day['data']])
    plt.xlabel('Time')
    plt.ylabel('Temperature (°C)')
    plt.title('Weather Patterns Over Time')
    plt.show()

def main():
    while True:
        current_data = []
        for api in [open_weather_map_api, dark_sky_api, wunderground_api]:
            data = get_weather_data(api)
            if data:
                current_data.append(data)

        for data in current_data:
            analysis = analyze_weather_data(data)
            if analysis == 'severe':
                send_email_notification(data)

        time.sleep(user_preferences['frequency'])

if __name__ == ""__main__"":
    main()
