def read_sort_extract(file_name):
    try:
        with open(file_name, 'r') as f:
            lines = [line.strip().split() for line in f.readlines()]
            sequence_numbers = [int(line[1]) for line in lines]
            sorted_lines = [x for _, x in sorted(zip(sequence_numbers, lines))]
            return int(sorted_lines[-1][1])
    except FileNotFoundError:
        print(f""Error: The file {file_name} does not exist."")
    except IOError as e:
        print(f""Error: An error occurred during file processing - {e}"")
