class Node:
    def __init__(self):
        self.val = None
        self.left = None
        self.right = None

class BST:
    def __init__(self, max_depth, num_nodes, data_capacity):
        self.max_depth = max_depth
        self.num_nodes = num_nodes
        self.data_capacity = data_capacity
        self.root = Node()
        self.node_count = 0
        self.allocate_memory()

    def allocate_memory(self):
        self.nodes = [Node() for _ in range(2 ** self.max_depth)]
        self.values = [None] * self.num_nodes

    def insert_node(self, depth, value):
        if depth >= self.max_depth:
            return
        mask = (1 << depth) - 1
        node_idx = (self.node_count >> depth) & mask
        left_child = 2 * node_idx + 1
        right_child = 2 * node_idx + 2
        if value < self.values[node_idx].val:
            if not self.values[left_child]:
                self.values[left_child] = self.nodes[node_idx].left = self.insert_node(depth + 1, value)
            else:
                self.values[left_child] = self.nodes[node_idx].left.val
        elif value > self.values[node_idx].val:
            if not self.values[right_child]:
                self.values[right_child] = self.nodes[node_idx].right = self.insert_node(depth + 1, value)
            else:
                self.values[right_child] = self.nodes[node_idx].right.val
        self.node_count += 1

    def construct_tree(self):
        for i in range(self.num_nodes):
            if not self.values[i]:
                self.values[i] = i
        self.insert_node(0, None)
