                chunk = decompressor.read(1024)
                while chunk:
                    decompressed_bytes.extend(chunk)
                    chunk = decompressor.read(1024)
                return decompressed_bytes
            else:
                raise ValueError(""Invalid compression level. It should be in the range of 1 to 9."")
