import xml.etree.ElementTree as ET
from typing import Any, Callable, Dict, List

class XMLHandler:
    _registry: Dict[str, Callable[[str], Any]] = {}

    def __init__(self):
        self._root_tag = 'root'

    @classmethod
    def register(cls, id: str, factory: Callable[[str], Any]) -> None:
        cls._registry[id] = factory

    @classmethod
    def from_string(cls, xml_str: str) -> Any:
        root = ET.fromstring(xml_str)
        return cls._deserialize(root)

    def to_string(self, obj: Any) -> str:
        root = self._serialize(obj)
        return ET.tostring(root, encoding='unicode')

    def _serialize(self, obj: Any) -> ET.Element:
        if isinstance(obj, dict):
            elem = ET.SubElement(ET.Element('obj'))
            for key, value in obj.items():
                subelem = self._serialize(value)
                subelem.tag = f'{{{self._root_tag}}{key.replace(""."", ""_"")}}'
                elem.append(subelem)
        elif hasattr(obj, '__dict__'):
            elem = ET.SubElement(ET.Element(self._root_tag))
            for key, value in obj.__dict__.items():
                subelem = self._serialize(value)
                subelem.tag = f'{{{self._root_tag}}{key.replace(""."", ""_"")}}'
                elem.append(subelem)
        elif hasattr(obj, '__xml__'):
            return ET.fromstring(obj.__xml__)
        else:
            raise ValueError(""Unsupported type"")
        return elem

    def _deserialize(self, root: ET.Element) -> Any:
        obj = {}
        for child in root:
            name = child.tag.split('}')[1].replace('{', '')
            if '.' not in name:
                name = f"".{name}""
            value = self._deserialize(child)
            if isinstance(value, dict):
                value = {k: v for k, v in value.items()}
            obj[name] = value
