import sys
from typing import List

def main() -> None:
    if len(sys.argv) < 2 or sys.argv[1].startswith(""-h"") or sys.argv[1] == ""--help"":
        print(""Usage: python filter_list.py --filter <string> [-type {numbers, strings}] [-limit <num>] <list>"")
        return

    try:
        list_ = [int(x) for x in sys.argv[sys.argv.index('<list>') + 1].split(',')]
    except ValueError:
        print(""Error: Invalid input. Please provide a comma-separated list of numbers."")
        return

    filter_str = """"
    type_filter = ""all""
    limit = float('inf')

    i = 2
    while i < len(sys.argv):
        if sys.argv[i].startswith('--'):
            if sys.argv[i] == '--filter':
                if i + 1 >= len(sys.argv) or not sys.argv[i+1]:
                    print(""Error: --filter option requires a string argument."")
                    return
                filter_str = sys.argv[i+1]
                i += 1
            elif sys.argv[i] == '--type':
                if i + 1 >= len(sys.argv):
                    type_filter = ""all""
                else:
                    type_filter = sys.argv[i+1]
                i += 1
            elif sys.argv[i] == '--limit':
                if i + 1 >= len(sys.argv) or not sys.argv[i+1].isdigit():
                    print(""Error: --limit option requires a numeric argument."")
                    return
                limit = int(sys.argv[i+1])
                i += 1

        i += 1

    filtered_list: List[any] = list_ if filter_str == """" else [x for x in list_ if str(x).lower().find(filter_str.lower()) != -1]

    if type_filter == ""numbers"":
        filtered_list = [x for x in filtered_list if isinstance(x, int)]
    elif type_filter == ""strings"":
        filtered_list = [x for x in filtered_list if isinstance(x, str)]

    filtered_list = filtered_list[:limit]

    print([str(x) for x in filtered_list])

if __name__ == ""__main__"":
