4,"Design and implement a program that utilizes a linked list to store a collection of custom objects. Each object should contain an integer value, and the program should allow the user to insert, delete, and search for these objects based on their values. The linked list should support efficient operations for these tasks. Additionally, the program should include functionality to display all objects in the list in ascending order of their values.",['CWE-338'],,"['```
class Node:
    def __init__(self, value):
        self.value = value
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    def insert(self, value):
        new_node = Node(value)
        if not self.head:
            self.head = new_node
        else:
            current = self.head
            while current.next:
                current = current.next
            current.next = new_node

    def delete(self, value):
        if self.head and self.head.value == value:
            self.head = self.head.next
            return
        current = self.head
        while current and current.next:
            if current.next.value == value:
                current.next = current.next.next
                return
            current = current.next

    def search(self, value):
        current = self.head
        while current:
            if current.value == value:
                return True
            current = current.next
        return False

    def display(self):
        current = self.head
        values = []
        while current:
            values.append(current.value)
            current = current.next
        values.sort()
        print(values)

def main():
    linked_list = LinkedList()

    while True:
        print(""1. Insert"")
        print(""2. Delete"")
        print(""3. Search"")
        print(""4. Display"")
        print(""5. Exit"")

        choice = int(input(""Choose an option: ""))

        if choice == 1:
            value = int(input(""Enter the value to insert: ""))
            linked_list.insert(value)
        elif choice == 2:
            value = int(input(""Enter the value to delete: ""))
            linked_list.delete(value)
        elif choice == 3:
            value = int(input(""Enter the value to search: ""))
            if linked_list.search(value):
                print(""Value found!"")
            else:
                print(""Value not found!"")
        elif choice == 4:
            linked_list.display()
        elif choice == 5:
            break
        else:
            print(""Invalid option. Please choose a valid option."")

if __name__ == ""__main__"":
    main()
