            path = ""myenv""
        else:
            path = args.path

        if not os.path.exists(path):
            os.makedirs(path)

        if args.packages:
            with open(f""{path}/requirements.txt"", 'w') as f:
                for package in args.packages:
                    f.write(f""{package}\n"")

        if args.activate:
            subprocess.run([sys.executable, ""-m"", ""venv"", ""--activate"", path], check=True)

        print(f""Virtual environment created at {path}"")

    except FileNotFoundError:
        print(""Error: Invalid path"")
        sys.exit(1)
    except Exception as e:
        print(f""Error: {str(e)}"")
        sys.exit(2)

def deactivate_virtual_environment(path):
    try:
        if not os.path.exists(path):
            print(""Error: Virtual environment does not exist"")
            return

        subprocess.run([os.path.join(path, ""Scripts"", ""activate.bat""), ""deactivate""], check=True)
    except Exception as e:
        print(f""Error: {str(e)}"")

def list_virtual_environments():
    try:
        for path in os.listdir(os.getcwd()):
            if os.path.isdir(path) and path.startswith(""myenv""):
                print(path)
    except Exception as e:
        print(f""Error: {str(e)}"")

if __name__ == ""__main__"":
    parser = argparse.ArgumentParser(description=""Create a virtual environment using the built-in venv module"")
    parser.add_argument(""-p"", ""--path"", help=""Path where the virtual environment should be created (default is 'myenv')"")
    parser.add_argument(""-P"", ""--packages"", nargs='+', help=""Packages to include during initialization (comma-separated list)"")
    parser.add_argument(""-a"", ""--activate"", action='store_true', help=""Activate the environment immediately after creation"")
    subparsers = parser.add_subparsers(dest='action')

    parser_create = subparsers.add_parser('create')
    parser_create.add_argument(""-p"", ""--path"", help=""Path where the virtual environment should be created (default is 'myenv')"")
    parser_create.add_argument(""-P"", ""--packages"", nargs='+', help=""Packages to include during initialization (comma-separated list)"")
    parser_create.add_argument(""-a"", ""--activate"", action='store_true', help=""Activate the environment immediately after creation"")

    parser_deactivate = subparsers.add_parser('deactivate')
    parser_deactivate.add_argument(""-p"", ""--path"", help=""Path of the virtual environment to deactivate"")

    parser_list = subparsers.add_parser('list')

    args = parser.parse_args()

    if args.action == 'create':
        create_virtual_environment(args)
    elif args.action == 'deactivate':
        deactivate_virtual_environment(args.path)
