import random
import argparse
import sys

def generate_random_nfa_list(size):
    return [f""UE-{i}: {random.randint(0, 100)}"" for i in range(1, size+1)]

def filter_by_criteria(lst, type=None, content=None):
    if not lst:
        return []

    if type == 'numbers':
        return [item for item in lst if isinstance(eval(item.split(':')[1]), int)]
    elif type == 'strings':
        return [item for item in lst if isinstance(eval(item.split(':')[1]), str)]

    if content is None:
        return lst

    return [item for item in lst if eval(item.split(':')[1]).strip().lower().__contains__(content.lower())]

def main():
    parser = argparse.ArgumentParser(description='Process a list by filtering and displaying its elements')
    parser.add_argument('-s', '--size', type=int, help='Size of the UE list')
    parser.add_argument('-t', '--type', choices=['numbers', 'strings'], default=None, help='Type of UE data (default: None)')
    parser.add_argument('-c', '--content', type=str, default=None, help='Content to filter by (default: None)')
    parser.add_argument('-l', '--limit', type=int, default=sys.maxsize, help='Maximum number of elements to display (default: sys.maxsize)')

    args = parser.parse_args()

    ue_list = generate_random_nfa_list(args.size)
    filtered_ue_list = filter_by_criteria(ue_list, type=args.type, content=args.content)
    for i, item in enumerate(filtered_ue_list[:args.limit]):
        print(f""{i+1}. {item}"")

if __name__ == ""__main__"":
    main()
