import subprocess
import os
import yaml

def read_yaml_file(file_path):
    with open(file_path, 'r') as file:
        config_data = yaml.safe_load(file)
    return config_data

def modify_kickstart_config(config_path, params, encrypted_password):
    if not os.path.isfile(config_path):
        raise FileNotFoundError(f""The file {config_path} does not exist."")

    output_file = 'modified_kickstart.cfg'
    with open(config_path, 'r') as f_in, open(output_file, 'w') as f_out:
        for line in f_in:
            for key, value in params.items():
                line = line.replace(key, str(value))
            f_out.write(line)

    sed_cmd = [
        ['s/DESIRED_PASSWORD_HERE/', encrypted_password],
        ['s/DESIRED_LINE_HERE/', ''],
        ['a/NEW_LINE_HERE/', '\n']
    ]

    for cmd in sed_cmd:
        try:
            subprocess.run(['sed', '-i', cmd[0], output_file], check=True)
        except subprocess.CalledProcessError as e:
            raise Exception(f""Failed to execute sed command: {cmd[0]}"")

    os.remove(config_path)
    os.rename(output_file, config_path)

def process_yaml_files(directory):
    if not os.path.isdir(directory):
        raise NotADirectoryError(f""The directory {directory} does not exist."")

    files_to_process = []

    for root_dir, _, files in os.walk(directory):
        for file in files:
            if file.endswith('.cfg'):
                files_to_process.append(os.path.join(root_dir, file))

    return files_to_process

def main():
    task_directory = ""path/to/directory""  # Replace with the path to the directory containing .cfg files
    processed_files = process_yaml_files(task_directory)

    config_params_list = [
        {'host_name': 'example_host', 'ip_address': '192.168.1.1'},
        {'host_name': 'another_host', 'ip_address': '192.168.2.2'}
       ]

    encrypted_passwords_list = ['example_encrypted_password', 'another_encrypted_password']

    if len(processed_files) != len(config_params_list) or len(processed_files) != len(encrypted_passwords_list):
         raise ValueError(""Mismatch between number of .cfg files and configuration parameters."")

    for i in range(len(processed_files)):
        modify_kickstart_config(processed_files[i], config_params_list[i], encrypted_passwords_list[i])

if __name__ == ""__main__"":
    main()
