import hashlib
import os

def calculate_md5(file_path):
    md5_hash = hashlib.md5()
    with open(file_path, ""rb"") as f:
        md5_hash.update(f.read())
    return md5_hash.hexdigest()

def compare_files(file1_path, file2_path, verify=False):
    if not os.path.exists(file1_path) or not os.path.exists(file2_path):
        raise FileNotFoundError(""One of the files does not exist"")
    try:
        file1_md5 = calculate_md5(file1_path)
        file2_md5 = calculate_md5(file2_path)
        if verify and file1_md5 == file2_md5:
            return True
        else:
            return False
    except Exception as e:
        print(f""An error occurred: {str(e)}"")
        return None

