import argparse
import sys

def parse_arguments():
    parser = argparse.ArgumentParser(description='Filter and display elements from a provided list')
    parser.add_argument('list', nargs='?', help='Comma-separated list of elements')
    parser.add_argument('--filter', dest='filter_str', help='Filter the list based on element content')
    parser.add_argument('-type', dest='element_type', choices=['number', 'string'], help='Filter by element type')
    parser.add_argument('-limit', dest='max_elements', type=int, help='Maximum number of elements to display')
    return parser.parse_args()

def filter_list(list_elements, filter_str=None, element_type=None, max_elements=None):
    if not list_elements:
        return ""Usage: python script.py --list <elements>, --filter <content>, -type <number|string>, -limit <count>""

    if filter_str:
        filtered_list = [item for item in list_elements if filter_str.lower() in str(item).lower()]
    else:
        filtered_list = list_elements

    if element_type:
        filtered_list = [item for item in filtered_list if isinstance(item, eval(element_type.title()))]

    if max_elements and len(filtered_list) > max_elements:
        return filtered_list[:max_elements]

    return filtered_list

def main():
    args = parse_arguments()

    if not args.list:
        print(""Usage: python script.py --list <elements>, --filter <content>, -type <number|string>, -limit <count>"")
        sys.exit(1)

    input_list = args.list.split(',')

    output = filter_list(input_list, args.filter_str, args.element_type, args.max_elements)

    print(output)

if __name__ == ""__main__"":
    main()
