import os

def modify_kickstart(config_path, param_dict, encrypted_password):
    try:
        with open(config_path, 'r') as config_file:
            lines = config_file.readlines()

        for placeholder, value in param_dict.items():
            lines = [line.replace(f'${placeholder}', str(value)) for line in lines]

        lines.append(f'password {encrypted_password}\n')

        new_config_path = 'modified_kickstart.cfg'
