        raise

def run_command_in_background(command):
    try:
        pid = os.fork()
        if pid == 0:
            os.execvp(command[0], command)
            raise Exception('Command execution failed')
    except Exception as e:
        print(f'Error occurred: {e}')
        return 0

    return 1

def main():
