from flask import Flask, request, jsonify
import json
from middlewares import AuthenticationMiddleware, RateLimitingMiddleware
from errors import InvalidUsageError, UnauthorizedError

app = Flask(__name__)

config_file = 'config.json'
with open(config_file) as f:
    config = json.load(f)

# Create middleware instances
auth_middleware = AuthenticationMiddleware(config['auth'])
rate_limiting_middleware = RateLimitingMiddleware(config['rate_limit'])

@app.before_request
def before_request():
    rate_limiting_middleware.check_rate_limit()
    auth_middleware.authenticate()

@app.errorhandler(InvalidUsageError)
def invalid_usage_error(error):
    return jsonify({'error': 'Invalid usage'}), 400

@app.errorhandler(UnauthorizedError)
def unauthorized_error(error):
    return jsonify({'error': 'Unauthorized'}), 401

@app.route('/')
def index():
    return 'Hello, World!'

if __name__ == '__main__':
    app.run(debug=True)
