import xml.etree.ElementTree as ET
from collections import defaultdict

def find_two_non_repeating_elements(lst):
    track = defaultdict(int)
    non_repeats = []

    for item in lst:
        if track[item] == 0:
            non_repeats.append(item)
            track[item] += 1
        else:
            track[item] -= 1

    return [item for item, count in track.items() if count == 0]

def load_configurations(xml_file_path):
    xdoc = ET.parse(xml_file_path)
    root = xdoc.getroot()

    config_settings = {}

    for child in root:
        config_settings[child.tag] = child.text

    return config_settings

def api_endpoint(request):
    if request.method == ""POST"":
        data = request.get_json()
        non_repeats = find_two_non_repeating_elements(data[""elements""])
        return {""non_repeats"": non_repeats}, 201
    elif request.method == ""GET"":
        config_settings = load_configurations(""config.xml"")
        resource_id = request.args.get(""resource_id"", None)

        if resource_id is not None:
            config_setting = config_settings.get(resource_id, None)
            return {""config"": config_setting}, 200
        else:
            return {""configs"": config_settings}, 200

from flask import Flask, request, jsonify
app = Flask(__name__)

@app.route('/api', methods=[""POST"", ""GET""])
def handle_request():
    return api_endpoint(request)

if __name__ == ""__main__"":
    app.run(debug=True)
