import os
import hashlib
import binascii

def generate_cryptographic_keys(num_keys: int):
    keys = []
    for _ in range(num_keys):
        while True:
            key_candidate = os.urandom(32)  # Generate a 256-bit random key
            key_hex = binascii.hexlify(key_candidate).decode('utf-8')  # Convert the key to hexadecimal string

            # Verify if the generated key is valid (e.g., not entirely zeros)
            if any(byte != 0 for byte in key_candidate):
                break

        keys.append(key_hex)

    return keys


def process_key(key: str, callback=None) -> None:
    if callback:
        callback(key)


def verify_keys(keys: list) -> bool:
    # Define the verification criteria (e.g., check for non-zero bytes)
    def is_valid_key(key: str) -> bool:
        key_bytes = binascii.unhexlify(key.encode('utf-8'))
        return any(byte != 0 for byte in key_bytes)

    # Check if all generated keys are valid
    return all(is_valid_key(key) for key in keys)


if __name__ == ""__main__"":
    num_keys = 10  # Specify the number of cryptographic keys to generate
    generated_keys = generate_cryptographic_keys(num_keys)

    print(""Generated Keys:"")
    for i, key in enumerate(generated_keys):
        process_key(key, lambda k: print(f""Key {i+1}: {k}""))

    if verify_keys(generated_keys):
        print(""All generated keys are valid."")
    else:
        print(""At least one generated key is invalid."")
