```python
from datetime import datetime, timedelta
from pytz import timezone, UnknownTimeZoneError
import unittest

def date_to_day(date_time_str: str, offset_hours: int = 0) -> str:
    try:
        dt_obj = datetime.strptime(date_time_str + "":00"", ""%Y-%m-%dT%H:%M:%S"")
        if offset_hours != 0:
            tz_name = 'US/Eastern' if offset_hours < 0 else 'US/Pacific'
            dt_obj = timezone(tz_name).localize(dt_obj).astimezone(timezone('UTC'))
        day_of_week = dt_obj.strftime(""%A"")[:3]
        return f""{day_of_week} {dt_obj.strftime('%H:%M:%S')} {dt_obj.strftime('%Z')}""
    except ValueError:
        return ""Invalid date""

class TestDateToDay(unittest.TestCase):
    def test_valid_dates(self):
        self.assertEqual(date_to_day(""2023-12-31T23:59:59""), ""Sun 23:59:59 UTC"")
        self.assertEqual(date_to_day(""1978-06-24T14:37:45+08:00""), ""Fri 14:37:45 CST"")

    def test_leap_year(self):
        self.assertEqual(date_to_day(""2024-02-29T18:59:59""), ""Sun 18:59:59 UTC"")

    def test_edge_cases(self):
        self.assertEqual(date_to_day(""1900-01-01T"", 3), ""Thu "")
        self.assertEqual(date_to_day(""2100-12-31T"", -4), ""Sun "")

    def test_invalid_date_format(self):
        self.assertEqual(date_to_day(""2023-12""), ""Invalid date"")
        self.assertEqual(date_to_day(""2023-12-31T23:59:59Z""), ""Invalid date"")

    def test_invalid_time_zone_offset(self):
        self.assertEqual(date_to_day(""1978-06-24T14:37:45+16:00""), ""Invalid date"")
        self.assertEqual(date_to_day(""1978-06-24T14:37:45-16:00""), ""Invalid date"")

    def test_unsupported_time_zone(self):
        self.assertEqual(date_to_day(""1978-06-24T14:37:45+ANTARTICA/HEARD""), ""Invalid date"")

if __name__ == ""__main__"":
    unittest.main()
