import rsa

def EncryptRSA(plaintext, public_key, modulus):
    if not isinstance(plaintext, str) or not plaintext.isprintable():
        raise ValueError(""Invalid input: plaintext must be a printable string"")

    try:
        public_key = int(public_key)
        modulus = int(modulus)
    except ValueError:
        raise ValueError(""Invalid input: public key and modulus must be integers"")

    if public_key < 0 or modulus < 0:
        raise ValueError(""Invalid input: public key and modulus must be positive integers"")

    plaintext_nums = [ord(c) for c in plaintext]
    encrypted_nums = rsa.encrypt(plaintext_nums, public_key, modulus)

    return int(''.join(map(str, encrypted_nums)))
