from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC
import random
import string

class SecureServiceManager:
    def __init__(self, db_config, amq_host):
        self.db = mysql.connector.connect(**db_config)
        self.amq = None if not amq_host else OpenSSL.connect(amq_host)

    def generate_symmetric_key(self):
        password = ''.join(random.choice(string.ascii_letters) for _ in range(32))
        salt = ''.join(random.choice(string.digits) for _ in range(16))
        kdf = PBKDF2HMAC(
            algorithm=hashes.SHA256(),
            length=32,
            salt=salt.encode('utf-8'),
            iterations=100000
        )
        key = base64.b64encode(kdf.derive(password.encode('utf-8')))
        return key

    def insert_random_data(self, table_name):
        cursor = self.db.cursor()
        try:
            for _ in range(1000):  # simulate inserting random data into a table
                values = []
                for column_type in ['int', 'float', 'varchar(50)']:
                    if column_type == 'int':
                        value = random.randint(1, 100)
                    elif column_type == 'float':
                        value = round(random.uniform(-10, 10), 2)
                    else:
                        value = ''.join(random.choice(string.ascii_letters) for _ in range(20))
                    values.append(f""'{value}'"")
                query = f""INSERT INTO {table_name} VALUES ({', '.join(values)})""
                cursor.execute(query)
            self.db.commit()
        except Exception as e:
            print(f""Error inserting data: {e}"")
        finally:
            if cursor:
                cursor.close()

    def encrypt_data(self, data):
        key = self.generate_symmetric_key()
        cipher = OpenSSL.AES_encrypt(data.encode('utf-8'), key.encode('utf-8'))
        return cipher

    def decrypt_data(self, encrypted_data):
        key = self.generate_symmetric_key()
        decrypted_data = OpenSSL.AES_decrypt(encrypted_data.encode('utf-8'), key.encode('utf-8'))
        return decrypted_data.decode('utf-8')

    def transmit_encrypted_data(self, data):
        if not self.amq:
            print(""ActiveMQ connection is not established"")
        else:
            try:
                self.amq.send(data)
            except Exception as e:
                print(f""Error transmitting data: {e}"")

    def handle_error(self, error):
        print(f""An error occurred: {error}"")
