import hashlib
import os

def calculate_md5_hash(file_path):
    md5 = hashlib.md5()
    with open(file_path, ""rb"") as file:
        # Read and update hash value with file data
        for chunk in iter(lambda: file.read(4096), b""""):
            md5.update(chunk)
    return md5.hexdigest()

def compare_md5_hashes(expected_hash, actual_hash):
    if expected_hash == actual_hash:
        print(""Hashes match."")
