import hashlib
import os
import json

class FileAnalyzer:
    def __init__(self, source_path, target_path):
        self.source_path = source_path
        self.target_path = target_path

    def calculate_md5_hash(self):
        try:
            with open(self.source_path, 'rb') as src_file:
                src_hash = hashlib.md5(src_file.read()).hexdigest()

            with open(self.target_path, 'rb') as tgt_file:
                tgt_hash = hashlib.md5(tgt_file.read()).hexdigest()

            if src_hash == tgt_hash:
                return ""Files match""
            else:
                return ""Files do not match""
        except IOError:
            return ""I/O Error occurred""

    def check_file_size(self):
        try:
            file_size = os.path.getsize(self.source_path)
            if file_size > 1048576:  # 1MB
                return ""File is larger than 1MB""
            else:
                return ""File size is within limit""
        except IOError:
            return ""I/O Error occurred""

class PokemonTypeHandlerJavaInterface:
    def __init__(self):
        self.pokemon_types_weaksnesses_json = 'pokemon_types_weaksnesses.json'

    def determine_weaknesses(self, pokemon_name):
        weaknesses_data = self.load_weaknesses_data()

        if pokemon_name in weaknesses_data.keys():
            weakness_type = weaknesses_data[pokemon_name]

            for type in weakness_type.keys():
                print(f""{type} is weakness"")

        else:
            print(""No specific weakness determined"")

    def load_weaknesses_data(self):
        with open(self.pokemon_types_weaksnesses_json) as json_file:
            data = json.load(json_file)

        return data

