import random

def generate_unique_random_numbers(num_entries):
    unique_numbers = []
    seen = set()
    for _ in range(num_entries):
        num = random.randint(0, 100)
        while num in seen:
            num = random.randint(0, 100)
        seen.add(num)
        yield num

def calculate_mean(unique_numbers):
    try:
        total_sum = sum(unique_numbers)
        mean = total_sum / len(unique_numbers)
        return mean
    except (ValueError, TypeError) as e:
        print(f""An error occurred: {e}"")
        return None

