import random
from nltk.corpus import words, brown
from nltk.tokenize import word_tokenize, sent_tokenize
from nltk.stem import WordNetLemmatizer

class PuzzleGenerator:
    def __init__(self):
        self.wordnet_lemmatizer = WordNetLemmatizer()
        self.all_words = set(words.words())
        self.brown_words = set(brown.words())

    def generate_puzzle(self, num_puzzles, complexity_level=1, time_constraint=300):
        puzzles = []
        for _ in range(num_puzzles):
            puzzle = {""phrase"": """", ""operation"": """", ""answer"": """"}
            if complexity_level == 1:
                phrase = self.generate_simple_phrase()
            elif complexity_level == 2:
                phrase = self.generate_medium_phrase()
            else:
                phrase = self.generate_complex_phrase()

            operation = random.choice([""synonym"", ""antonym"", ""anagram""])
            answer = self.apply_operation(phrase, operation)

            puzzle[""phrase""] = phrase
            puzzle[""operation""] = operation
            puzzle[""answer""] = answer

            puzzles.append(puzzle)

        return puzzles

    def generate_simple_phrase(self):
        adjective = random.choice([word for word in self.all_words if len(word) == 5])
        noun = random.choice([word for word in self.all_words if len(word) > 5])
        verb = random.choice([word for word in self.all_words if len(word) == 4])
        phrase = f""{adjective} {noun} {verb}""
        return phrase

    def generate_medium_phrase(self):
        sentence = random.choice(brown.sents())
        return "" "".join(sentence)

    def generate_complex_phrase(self):
        sentence = random.choice(brown.sents())
        words = word_tokenize(sentence)
        adjective_index = random.randint(0, len(words) - 1)
        noun_index = random.randint(adjective_index + 1, len(words) - 1)
        verb_index = random.randint(0, len(words) - 1)
        phrase = "" "".join([words[i] for i in range(len(words)) if i not in [adjective_index, noun_index, verb_index]]) + f"" {self.wordnet_lemmatizer.lemmatize(words[adjective_index], 'a')} {self.wordnet_lemmatizer.lemmatize(words[noun_index], 'n')} {self.wordnet_lemmatizer.lemmatize(words[verb_index], 'v')}""
        return phrase

    def apply_operation(self, phrase, operation):
        if operation == ""synonym"":
            words = phrase.split()
            for i in range(len(words)):
                if len(words[i]) > 5:
                    synonyms = [word for word in self.all_words if wordnet_lemmatizer.lemmatize(word, 'n') == words[i]]
                    if synonyms:
                        words[i] = random.choice(synonyms)
            return "" "".join(words)
        elif operation == ""antonym"":
            words = phrase.split()
            for i in range(len(words)):
                if len(words[i]) > 5:
                    antonyms = [word for word in self.all_words if wordnet_lemmatizer.lemmatize(word, 'n') != words[i]]
                    if antonyms:
                        words[i] = random.choice(antonyms)
            return "" "".join(words)
        else:
            anagrammed_phrase = "" "".join(["""".join(sorted(word)) for word in phrase.split()])
            return anagrammed_phrase

    def evaluate_solution(self, solution):
        # TO DO: implement evaluation mechanism
        pass

