import hashlib
import json

class FileAnalyzer:
    def __init__(self, file1, file2):
        self.file1 = file1
        self.file2 = file2

    def calculate_md5_hash(self):
        with open(self.file1, 'rb') as f1, open(self.file2, 'rb') as f2:
            hash1 = hashlib.md5(f1.read()).hexdigest()
            hash2 = hashlib.md5(f2.read()).hexdigest()
            if hash1 == hash2:
                return ""Files match""
            else:
                return ""Files do not match""

    def check_file_size(self):
        with open(self.file1, 'rb') as f:
            file_size = f.seek(0, 2)
            if file_size > 1024 * 1024:
                return ""File size is larger than 1MB""
            else:
                return ""File size is less than or equal to 1MB""


class PokemonTypeHandlerJavaInterface:
    def __init__(self):
        with open('pokemon_type_weaknesses.json', 'r') as f:
            self.pokemon_data = json.load(f)

    def determine_weaknesses(self, pokemon_name):
        if pokemon_name in self.pokemon_data['weaknesses']:
            for weakness in self.pokemon_data['weaknesses'][pokemon_name]:
                print(weakness)
        else:
            print(""No specific weakness determined"")


# Usage
