class Registry:
    def __init__(self):
        self.factories = {}

    def register(self, id, factory):
        self.factories[id] = factory

    def instantiate(self, id, data):
        if id in self.factories:
            return self.factories[id](data)
        else:
            raise ValueError(f""No factory registered for ID '{id}'"")


class JSONConverter:
    def __init__(self, registry):
        self.registry = registry

    def to_json(self, obj):
        return json.dumps(obj.__dict__)

    def from_json(self, data, id):
        try:
            return self.registry.instantiate(id, json.loads(data))
        except ValueError as e:
            raise ValueError(f""Failed to instantiate object: {str(e)}"")


class FactoryMeta(type):
    def __new__(mcs, name, bases, attrs):
        factory_id = attrs.get('factory_id')
        if factory_id is None:
            raise AttributeError(""Factory ID must be specified for subclass"")

        class factory(mcs):
            def __call__(self, data):
                instance = super().__call__({'data': data})
                return Registry().register(factory_id, self.__class__)
                pass

        return factory


def register_factory(cls):
    cls.factory_id = id(cls)
    return cls
