def generate_ble_advertisements(count, random_seed, max_advertisement_length, allocate_on_stack=False):
    if count <= 0:
        return None

    try:
        random.seed(random_seed)
        advertisements = []

        for _ in range(count):
            timestamp = int(random.randint(1, 2**32 - 1))
            data_payload = bytes([random.getrandbits(8) for _ in range(max_advertisement_length)])
