import numpy as np
import nltk
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.metrics.pairwise import cosine_similarity

class TextSummarizer:
    def __init__(self, max_summary_length):
        self.max_summary_length = max_summary_length

    def generate_summary(self, article):
        sentences = nltk.sent_tokenize(article)
        sentence_scores = self.calculate_sentence_scores(sentences)
        selected_sentences = self.select_top_sentences(sentence_scores)
        summary = ' '.join(selected_sentences)
        return summary[:self.max_summary_length]

    def calculate_sentence_scores(self, sentences):
        vectorizer = TfidfVectorizer()
        tfidf_matrix = vectorizer.fit_transform(sentences)
        sentence_scores = cosine_similarity(tfidf_matrix, tfidf_matrix).diagonal()
        return sentence_scores

    def select_top_sentences(self, sentence_scores):
        sorted_indices = np.argsort(sentence_scores)[::-1]
        top_indices = sorted_indices[:self.max_summary_length]
        return [sentences[i] for i in top_indices]

