import random
import xml.etree.ElementTree as ET

class TileSize:
    def __init__(self, width, height):
        self.width = width
        self.height = height
        self.load_xml_config()

    def load_xml_config(self):
        try:
            tree = ET.parse('game_env.xml')
            root = tree.getroot()
            for size in root.findall('size'):
                self.width = int(size.find('width').text)
                self.height = int(size.find('height').text)
                break
        except FileNotFoundError:
            print(""XML file not found."")
        except ET.ParseError:
            print(""Error parsing XML file."")

class WorldConfig:
    def __init__(self, width, height, camera_speed):
        self.width = width
        self.height = height
        self.camera_speed = camera_speed

    @property
    def world_width(self):
        return (self.width // 16) * 16

    @classmethod
    def from_xml(cls, config_file_path):
        tree = ET.parse(config_file_path)
        root = tree.getroot()

        if 'world_width' not in root.attrib.keys():
            raise ValueError(""Missing 'world_width' attribute in XML file"")

        world_width = int(root.attrib['world_width'])

        return cls(
            width=world_width,
            height=int(root.attrib['height']),
            camera_speed=int(root.attrib['camera_speed'])
        )

