class KeyManager:
    def __init__(self):
        self.keys = {}
        self.key_certificates = {}
        self.cert_stores = []

    def generate_key(self, username: str, password: str) -> Ed25519PublicKey:
        # Generate a new keypair
        public_key = Ed25519PublicKey.generate()

        # Store the keypair in the database
        self.keys[username] = {
            ""public_key"": public_key.public_bytes(
                encoding=serialization.Encoding.OpenSSH,
                format=serialization.PublicFormat.Standard,
            ),
            ""private_key"": None,
        }

        return public_key

    def generate_multiple_keys(self, usernames: list, password: str) -> dict:
        # Generate a new keypair for each username
        keys = {}
        for username in usernames:
            keys[username] = self.generate_key(username, password)

        return keys

