            ),
            serial_number=self.generate_serial_number(),
        )

        return None

    def retrieve_key(self, username: str) -> Ed25519PublicKey:
        # Retrieve the public key from the database
        public_key = self.keys[username][""public_key""]
        certificate = self.key_certificates[username]

        return public_key, certificate

    def revoke_key(self, username: str) -> None:
        # Revoke the public key in the database
        del self.keys[username]
        del self.key_certificates[username]

