class KeyRotator:
    def __init__(self, key_manager):
        self.key_manager = key_manager
        self.rotation_interval = 30 * 24 * 60 * 60  # Rotate every 30 days

    def rotate_keys(self) -> None:
        # Check if it's time to rotate the keys
        current_timestamp = datetime.now().timestamp()
        last_rotation_timestamp = self.key_manager.get_last_rotation_timestamp()

        if current_timestamp - last_rotation_timestamp >= self.rotation_interval:
            # Rotate the keys
            new_keys = {}
            for username, public_key in self.key_manager.keys.items():
                new_public_key = Ed25519PublicKey.generate()

                new_keys[username] = {""public_key"": new_public_key.public_bytes()}

            self.key_manager.update_keys(new_keys)

        return None

class KeyRevoker:
    def __init__(self, key_manager):
        self.key_manager = key_manager
        self.revocation_interval = 30 * 24 * 60 * 60  # Revoke every 30 days

    def revoke_key(self, username: str) -> None:
        # Check if it's time to revoke the key
        current_timestamp = datetime.now().timestamp()
        last_revocation_timestamp = self.key_manager.get_last_revocation_timestamp(username)

        if current_timestamp - last_revocation_timestamp >= self.revocation_interval:
            # Revoke the key
            self.key_manager.revoke_key(username)

        return None

