import os

class FileAnalyzer:
    def __init__(self, file1, file2):
        self.file1 = file1
        self.file2 = file2

    def calculate_md5_hash(self):
        with open(self.file1, 'rb') as f1:
            content1 = f1.read()
            md5_1 = hashlib.md5(content1).hexdigest()

        with open(self.file2, 'rb') as f2:
            content2 = f2.read()
            md5_2 = hashlib.md5(content2).hexdigest()

        if md5_1 == md5_2:
            return ""Files match""
        else:
            return ""Files do not match""

    def check_file_size(self):
        size_in_bytes = os.path.getsize(self.file1)
        if size_in_bytes > 1000000:
            return ""Source file is larger than 1MB""
        else:
            return ""Source file is smaller or equal to 1MB""

