        if structure_ptr.src_mac_address is None or not isinstance(structure_ptr.src_mac_address, str) or len(structure_ptr.src_mac_address.replace(':', '')) != 12:
            return False

        if not isinstance(structure_ptr.type, str):
            return False

        return True

    def create_and_print_first_5_frames(structure_array):

