// Python Function for file hash computation using SHA-256 algorithm
def compute_file_hash(file_path):
    import hashlib

    sha256_hash = hashlib.sha256()
    with open(file_path, 'rb') as f:
        # Read the file in chunks to avoid loading entire file into memory
        while True:
            chunk = f.read(4096)
            if not chunk:
                break
            sha256_hash.update(chunk)

    return sha256_hash.hexdigest()

